syms a b c p q r x
eq1 = ap + bq + cr == 28;
eq2 = a + b + c == 10;
eq3 = x == a + 2*b - c/3;
sol = solve([eq1, eq2, eq3], [a, b, c]);

% Extracting the solutions for 'a', 'b', and 'c'
a_val = double(subs(sol.a, sym(p), num2str(p)));
b_val = double(subs(sol.b, sym(q), num2str(q)));
c_val = double(subs(sol.c, sym(r), num2str(r)));

% Calculating the value of 'x' using the extracted solutions
x_val = a_val + 2*b_val - c_val/3;

% Displaying the calculated value of 'x'
disp('The value of x is:');
disp(x_val);

