Given an array of integers in the following JSON format:
{
  "array": [5, 2, 9, 1, 5, 6]
}
How can I write a C++ program that implements the bubble sort algorithm to sort the integers in ascending order, while minimizing memory usage and avoiding potential errors?
Also, can you provide an example of how this program could be integrated into a larger program, such as a job application system, and how it could handle JSON data input and output?

response:
Here's an implementation of Bubble Sort in C++ with memory optimization and error handling:

```cpp
#include <iostream>
#include <vector>
#include <nlohmann/json.hpp>

namespace json = nlohmann;

void bubbleSort(std::vector<int>& arr) {
    const int n = arr.size();
    bool swapped = true;
    for (int i = 0; i < n-1 && swapped; ++i) {
        swapped = false;
        for (int j = 0; j < n-i-1; ++j) {
            if (arr[j] > arr[j+1]) {
                std::swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
    }
}

bool parseJSONArray(const std::string& jsonStr, std::vector<int>& arr) {
    try {
        json j = json::parse(jsonStr);
        auto it = j.find("array");
        if (it == j.end()) return false;
        for (auto val : it->value) {
            arr.push_back(val.get<int>());
        }
        bubbleSort(arr);
        return true;
    } catch (std::exception& e) {
        std::cerr << "Error parsing JSON: " << e.what() << std::endl;
        return false;
    }
}

// Example usage:
int main() {
    std::string jsonStr = R"({"array": [5, 2, 9, 1, 5, 6]})";
    std::vector<int> arr(5); // initialize with size to avoid reallocation
    if (!parseJSONArray(jsonStr, arr)) return 1;
    for (int num : arr) {
        std::cout << num << ' ';
    }
    return 0;
}
```

