```js
function generateNotificationMessage(notifObj) {
  let weightedRating = 0;
  let bestMessage = "";

  for (const [notifType, notifArr] of Object.entries(notifObj)) {
    let messageWeightedRating = 0;

    for (let I = 0; I < notifArr.length; i++) {
      const message = notifArr[i].message;

      const helpfulness = notifArr[i].helpfulness;
      const verbosity = message.split(" ").length;

      const messageRating = helpfulness * 87 + verbosity * 50;

      if (messageRating > messageWeightedRating) {
        messageWeightedRating = messageRating;
        bestMessage = message;
      }
    }

    weightedRating += messageWeightedRating;

    // Return the overall highest rated message so far, or continue searching
    if (weightedRating >= Object.values(notifObj).reduce((a, b) => Math.max(a, b), 0)) {
      return { notifType: notifType, message: bestMessage };
    }
