   ```javascript
   import App from 'next/app';
   import withCors from 'next-cors';

   class MyApp extends App {
     componentDidMount() {
       // Any initialization logic here...
     }

     render() {
       const { Component, pageProps } = this.props;

       return (
         <Component {...pageProps} />
       );
     }
   }

   export default withCors(MyApp);
   ```

4. Finally, update your `package.json` script to start your Next.js app with the new configuration:
   ```json
   "scripts": {
     "dev": "next dev",
     "build": "next build"
   },
   ```

